    updateAccountsFilter: function () {
        let accounts = xabber.accounts.enabled,
            selected_jid;
        if (this.current_filter_account){
            selected_jid = this.current_filter_account;
        }
        this.$('.tab-account-filter-item').switchClass('hidden', accounts.length === 1 || !accounts.length);
        if (accounts.length){
            try{
                this.$('.additional-filter-variant').remove();
                _.each(accounts, (account) => {
                    this.$('.accounts-dropdown').append($(`<div class="property-variant btn-accounts-filter additional-filter-variant" data-jid="${account.get('jid')}"><span class="one-line">${account.get('jid')}</span></div>`));
                });
                if (selected_jid && selected_jid === 'all'){
                    this.current_filter_account = 'all';
                    this.account = null;
                    this.updateGroupsFilter();
                    this.processUpdateContacts(null, true);

                } else if (selected_jid && accounts.find(item => item.get('jid') === this.current_filter_account)){
                    this.current_filter_account = selected_jid;
                    this.account = accounts.find(item => item.get('jid') === this.current_filter_account);
                    this.updateGroupsFilter();
                    this.processUpdateContacts(null, true);
                    this.processUpdateContacts(null, true);
                } else if (accounts.length === 1) {
                    this.account = accounts[0];
                    this.current_filter_account = this.account.get('jid');
                    this.updateGroupsFilter();
                    this.processUpdateContacts(true, true);
                } else {
                    this.current_filter_account = 'all';
                    this.account = null;
                    this.updateGroupsFilter();
                    this.processUpdateContacts(true, true);
                }
                this.updateAllIncomingSubscriptions();
            } catch (e) {
                console.error(e)
            }
        } else {
            if (!xabber.accounts.enabled.length){
                if (xabber.body.screen.get('name') === 'contacts'){
                    xabber.toolbar_view.showAllChats(null, true);
                } else if (xabber.body.screen.get('previous_screen') && xabber.body.screen.get('previous_screen').name === 'contacts') {
                    this.$el.detach();
                    xabber.toolbar_view.$('.toolbar-item:not(.account-item):not(.toolbar-logo)').removeClass('active');
                    let previous_chat = xabber.body.screen.get('previous_screen');
                    previous_chat.open_all_chats = true;
                    xabber.body.screen.set('previous_screen', previous_chat);
                }
            }
        }
    },

    updateGroupsFilterDebounced: function () {
        let accounts = xabber.accounts.enabled,
            account = accounts.find(item => item.get('jid') === this.current_filter_account);

        if (account){
            this.$('.contacts-group-filter-content').empty();
            _.each(account.groups.models, (group) => {
                let custom_count_value;
                if (group.get('id') === constants.GENERAL_GROUP_ID && group.get('name') === xabber.settings.roster.general_group_name)
                    return;
                if (group.get('id') === constants.NON_ROSTER_GROUP_ID && group.get('name') === xabber.settings.roster.non_roster_group_name)
                    return;
                if (this.current_filter.type === 'groupchat' && group.contacts.some(item => item.get('group_chat'))){
                    custom_count_value = group.contacts.filter(item => item.get('group_chat')).length;
                }
                if (this.current_filter.type === 'contacts' && group.contacts.some(item => !item.get('group_chat'))){
                    custom_count_value = group.contacts.filter(item => !item.get('group_chat')).length;
                }
                if (this.current_filter.type && this.current_filter.type !== 'subscription' && !custom_count_value){
                    custom_count_value = 0
                }
                this.$('.contacts-group-filter-content').append(this.renderGroupFilterItem(group, custom_count_value));
            });
        } else {
            if(this.current_filter_account === 'all' && accounts.length){
                this.$('.contacts-group-filter-content').empty();
                _.each(accounts, (account) => {
                    _.each(account.groups.models, (group) => {
                        let custom_count_value;
                        if (group.get('id') === constants.GENERAL_GROUP_ID && group.get('name') === xabber.settings.roster.general_group_name)
                            return;
                        if (group.get('id') === constants.NON_ROSTER_GROUP_ID && group.get('name') === xabber.settings.roster.non_roster_group_name)
                            return;
                        if (this.current_filter.type === 'groupchat' && group.contacts.some(item => item.get('group_chat'))){
                            custom_count_value = group.contacts.filter(item => item.get('group_chat')).length;
                        }
                        if (this.current_filter.type === 'contacts' && group.contacts.some(item => !item.get('group_chat'))){
                            custom_count_value = group.contacts.filter(item => !item.get('group_chat')).length;
                        }
                        if (this.current_filter.type && this.current_filter.type !== 'subscription' && !custom_count_value){
                            custom_count_value = 0
                        }
                        if (this.$(`.filter-item-wrap[data-groupname="${group.get('id')}"]`).length){
                            let $group = this.$(`.filter-item-wrap[data-groupname="${group.get('id')}"]`);
                            if ($group.find('span').text() && Number($group.find('span').text())){
                                let initial_count = Number($group.find('span').text());
                                if (!_.isUndefined(custom_count_value))
                                    $group.find('span').text(initial_count + custom_count_value);
                                else
                                    $group.find('span').text(initial_count + group.get('counter').all);
                            }
                        } else {
                            this.$('.contacts-group-filter-content').append(this.renderGroupFilterItem(group, custom_count_value));
                        }
                    });
                })
            }

        }
        this.$('.contacts-group-filter').switchClass('hidden', !this.$('.contacts-group-filter-content .filter-item-wrap').length);
        _.each(this.current_filter_groups_list, (item) => {
            this.$(`.filter-item-wrap[data-groupname="${item}"]`).addClass('selected-filter');
        });
        this.updateScrollBar2();
        this.updateAccountColor(account);
    },

    updateGroupsFilter: function () {
        this.circle_debounce();
    },

    renderAccountItem: function (account) {
        return $(env.templates.notifications.account_filter_item({jid: account.get('jid'), color: account.settings.get('color')}));
    },

    renderGroupFilterItem: function (group, custom_count_value) {
        let counter = group.get('counter').all;
        if (!_.isUndefined(custom_count_value)){
            counter = custom_count_value;
        }
        return $(templates.group_filter_item({id: group.get('id'), name: group.get('name'), counter: counter }));
    },

