xabber.Account.addInitPlugin(function () {
    this.groups_settings = new xabber.GroupsSettings(null, {
        account: this,
        storage_name: xabber.getStorageName() + '-groups-settings-' + this.get('jid')
    });
    this.cached_roster = new xabber.CachedRoster(null, {
        name:'cached-roster-list-' + this.get('jid') + '-' + this.get('account_unique_id'),
        objStoreName: 'roster_items',
        primKey: 'jid'
    });
    this.cached_sync_conversations = new xabber.CachedSyncConversations(null, {
        name:'cached-conversation-list-v108-' + this.get('jid') + '-' + this.get('account_unique_id'),
        objStoreName: 'conversation_items',
        primKey: 'account_conversation_type'
    });
    this.cached_notifications = new xabber.CachedNotifications(null, {
        name:'cached-notification-list-v108-' + this.get('jid') + '-' + this.get('account_unique_id'),
        objStoreName: 'notification_items',
        primKey: 'stanza_id'
    });
    this.cached_calls = new xabber.CachedCalls(null, {
        name:'cached-calls-list-v108-' + this.get('jid') + '-' + this.get('account_unique_id'),
        objStoreName: 'call_items',
        primKey: 'stanza_id'
    });
    this.cached_server_features = new xabber.CachedServerFeatures(null, {
        name:'cached-features-list-' + this.get('jid') + '-' + this.get('account_unique_id'),
        objStoreName: 'server_features_items',
        primKey: 'var'
    });

    this.groupchat_settings = new xabber.GroupChatSettings({id: 'group-chat-settings'}, {
        account: this,
        storage_name: xabber.getStorageName() + '-group-chat-settings-' + this.get('jid'),
        fetch: 'after'
    });
    this.groups = new xabber.Groups(null, {account: this});
    this.contacts = new xabber.Contacts(null, {account: this});

    this.cached_roster.on("database_open_failed", () => {
        this.contacts.addCollection(this.roster = new xabber.Roster(null, {account: this, roster_version: 0}));
        this.trigger('roster_created');
    });

    this.cached_roster.on("database_opened", () => {
        this.cached_roster.getFromRoster('roster_version', (res) => {
            let roster_version = res && res.version ? res.version : 0;
            this.contacts.addCollection(this.roster = new xabber.Roster(null, {account: this, roster_version: roster_version}));
            this.trigger('roster_created');
        });
    });

    this.blocklist = new xabber.BlockList(null, {account: this});

    this._added_pres_handlers.push(this.contacts.handlePresence.bind(this.contacts));

    this.on("ready_to_get_roster", function () {
        let dfd = new $.Deferred();
        dfd.done(() => {
            let resumed;
            if (this.connection && this.connection.streamManagement){
                if (!(this.connection.streamManagement._isStreamManagementEnabled && this.connection.streamManagement.getResumeToken())){
                    resumed = false;
                    this.connection.streamManagement.enable(true);
                } else if (this.connection.streamManagement._isStreamManagementEnabled && this.connection.streamManagement.getResumeToken()) {
                    resumed = true;
                }
            }
            if (!resumed){
                this.resources.reset();
                this.contacts.each(function (contact) {
                    contact.resources.reset();
                    contact.resetStatus();
                });
            }
            this.cached_roster.getAllFromRoster((roster_items) => {
                $(roster_items).each((idx, roster_item) => {
                    if (roster_item.jid === 'roster_version'){
                        return;
                    }
                    this.contacts.mergeContact(roster_item);
                });
                if (this.connection && this.connection.do_synchronization && xabber.chats_view) {
                    let options = {};
                    this.cached_sync_conversations.getFromCachedConversations('last_sync_timestamp', (res) => {
                        let last_sync_timestamp = res && res.timestamp ? res.timestamp : null;
                        !this.roster.last_chat_msg_id && (options.max = constants.SYNCHRONIZATION_RSM_MAX);
                        last_sync_timestamp && (options.stamp = last_sync_timestamp);
                        this.roster.syncFromServer(options, Boolean(last_sync_timestamp), true);
                        this.roster.getRoster();
                    });
                }
                else {
                    this.roster.getRoster();
                    this.sendPresence();
                    this.dfd_presence.resolve();
                }
                this.blocklist.getFromServer();
            });
        });
        console.log(this.roster);
        if (this.roster) {
            dfd.resolve();
        } else {
            this.once('roster_created', () => {
                dfd.resolve();
            });
        }
    }, this);
});

xabber.Account.addConnPlugin(function () {
    this.registerIQHandler();
    this.registerSyncedIQHandler();
    if (this.roster) {
        this.roster.registerHandler();
    } else {
        this.once('roster_created', () => {
            this.roster.registerHandler();
        });
    }
    this.blocklist.registerHandler();
}, true, true);

xabber.once("start", function () {
    this._roster_settings = new this.RosterSettings({id: 'roster-settings'},
        {storage_name: this.getStorageName(), fetch: 'after'});
    this.settings.roster = this._roster_settings.attributes;

    !this.contacts_view && (this.contacts_view = new xabber.RosterFullScreenView({model: this.accounts}));

    this.contacts_body = this.right_panel.addChild('contacts_body',
        this.ContactsBodyContainer);
    this.contacts_left_view = this.left_panel.addChild('contacts-left', this.RosterLeftView,
        {model: this.accounts});
    this.contact_container = this.right_panel.addChild('details', this.Container);
    this.details_container = this.right_contact_panel.addChild('details', this.Container);
    this.add_contact_view = new this.AddContactView();
    this.on("add_contact", function () {
        this.add_contact_view.show();
    }, this);
}, xabber);

export default xabber;